styleContent:
/* ============ TOKENS ============ */
:root{
  --ink:#1B2A38;
  --ink-soft:#22324290;
  --ink-panel:#243447;
  --paper:#F3ECDD;
  --paper-soft:#FBF8F0;
  --paper-line:#E3D9C2;
  --tape:#B23A2E;
  --tape-dark:#8C2C22;
  --brass:#B8965A;
  --brass-soft:#B8965A55;
  --charcoal:#241F1A;
  --bone:#EFE9DC;
  --bone-faint:rgba(239,233,220,0.62);
  --bone-faint2:rgba(239,233,220,0.4);
  --shadow:0 18px 40px -18px rgba(0,0,0,0.45);
  --radius:2px;
  --font-display:'Fraunces', serif;
  --font-body:'IBM Plex Sans','IBM Plex Sans Devanagari',sans-serif;
  --font-mono:'IBM Plex Mono', monospace;
}

*{box-sizing:border-box;}
html{scroll-behavior:smooth; scroll-padding-top:88px;}
body{
  margin:0;
  background:var(--ink);
  color:var(--bone);
  font-family:var(--font-body);
  font-size:16px;
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%;display:block;}
a{color:inherit;text-decoration:none;}
ul{margin:0;padding:0;list-style:none;}
h1,h2,h3{margin:0;font-family:var(--font-display);font-weight:600;letter-spacing:-0.01em;}
p{margin:0;}
button{font-family:inherit;cursor:pointer;}

:focus-visible{
  outline:2px solid var(--brass);
  outline-offset:3px;
  border-radius:1px;
}

.wrap{
  max-width:1180px;
  margin:0 auto;
  padding:0 32px;
}

.eyebrow{
  font-family:var(--font-mono);
  font-size:11.5px;
  letter-spacing:0.16em;
  text-transform:uppercase;
  display:inline-flex;
  align-items:center;
  gap:8px;
}

.devanagari{font-family:'IBM Plex Sans Devanagari', sans-serif;}

/* ============ NAV ============ */
header.site-nav{
  position:sticky;
  top:0;
  z-index:80;
  background:rgba(27,42,56,0.92);
  backdrop-filter:blur(10px);
  border-bottom:1px solid var(--brass-soft);
  transition:box-shadow .25s ease, background .25s ease;
}
header.site-nav.is-scrolled{
  box-shadow:0 12px 30px -16px rgba(0,0,0,0.55);
  background:rgba(27,42,56,0.98);
}
.nav-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:16px 32px;
  max-width:1180px;
  margin:0 auto;
}
.brand{
  display:flex;
  align-items:center;
  gap:10px;
  font-family:var(--font-display);
  font-size:21px;
  font-weight:600;
  color:var(--bone);
}
.brand-seal{
  width:34px;height:34px;flex:none;
  border-radius:50%;
  border:1.5px solid var(--brass);
  display:flex;align-items:center;justify-content:center;
  position:relative;
}
.brand-seal::before{
  content:"";
  position:absolute;inset:4px;
  border:1px dashed var(--brass-soft);
  border-radius:50%;
}
.brand-seal svg{width:16px;height:16px;}
.brand-text small{
  display:block;
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--bone-faint);
  font-weight:400;
  margin-top:1px;
}

.nav-links{
  display:flex;
  align-items:center;
  gap:34px;
}
.nav-links a{
  font-size:14.5px;
  color:var(--bone-faint);
  position:relative;
  padding:4px 0;
  transition:color .2s ease;
}
.nav-links a:hover{color:var(--bone);}
.nav-links a::after{
  content:"";
  position:absolute;left:0;bottom:-2px;
  width:0;height:1px;background:var(--tape);
  transition:width .2s ease;
}
.nav-links a:hover::after{width:100%;}

.nav-actions{display:flex;align-items:center;gap:14px;}
.nav-signin{font-size:14px;color:var(--bone-faint);}
.nav-signin:hover{color:var(--bone);}

.nav-burger{
  display:none;
  flex-direction:column;
  gap:4px;
  background:none;border:none;padding:6px;
}
.nav-burger span{width:22px;height:2px;background:var(--bone);display:block;border-radius:1px;}

/* ============ BUTTONS ============ */
.btn{
  font-family:var(--font-body);
  font-weight:600;
  font-size:14.5px;
  padding:13px 24px;
  border-radius:var(--radius);
  display:inline-flex;
  align-items:center;
  gap:8px;
  border:1px solid transparent;
  transition:transform .15s ease, box-shadow .15s ease, background .15s ease;
  white-space:nowrap;
}
.btn:active{transform:translateY(2px) scale(0.99);}
.btn-stamp{
  background:var(--tape);
  color:var(--paper-soft);
  box-shadow:0 10px 24px -10px rgba(178,58,46,0.7);
}
.btn-stamp:hover{background:var(--tape-dark);}
.btn-ghost{
  background:transparent;
  border:1px solid var(--brass-soft);
  color:var(--bone);
}
.btn-ghost:hover{border-color:var(--brass); background:rgba(184,150,90,0.08);}
.btn-dark{
  background:var(--ink-panel);
  color:var(--bone);
  border:1px solid var(--brass-soft);
}
.btn-dark:hover{border-color:var(--brass);}
.btn-sm{padding:9px 16px;font-size:13px;}

/* ============ HERO ============ */
.hero{
  position:relative;
  padding:88px 0 96px;
  overflow:hidden;
}
.hero::before{
  content:"";
  position:absolute; inset:0;
  background:
    radial-gradient(ellipse 700px 420px at 18% -10%, rgba(184,150,90,0.16), transparent 60%),
    radial-gradient(ellipse 600px 500px at 95% 30%, rgba(178,58,46,0.10), transparent 60%);
  pointer-events:none;
}
.hero-grid{
  position:relative;
  display:grid;
  grid-template-columns:1.05fr 0.95fr;
  gap:64px;
  align-items:center;
}
.hero-eyebrow{
  color:var(--brass);
  margin-bottom:22px;
}
.hero-eyebrow .dot{width:5px;height:5px;border-radius:50%;background:var(--tape);display:inline-block;}

h1.hero-title{
  font-size:clamp(34px, 4.4vw, 54px);
  line-height:1.08;
  color:var(--paper-soft);
  max-width:600px;
}
h1.hero-title em{
  font-style:italic;
  color:var(--bone);
  text-decoration:underline;
  text-decoration-color:var(--tape);
  text-decoration-thickness:3px;
  text-underline-offset:6px;
}
.hero-sub{
  margin-top:22px;
  font-size:17px;
  color:var(--bone-faint);
  max-width:480px;
}
.hero-cta{
  margin-top:34px;
  display:flex;
  gap:14px;
  flex-wrap:wrap;
}
.hero-micro{
  margin-top:20px;
  font-family:var(--font-mono);
  font-size:12.5px;
  letter-spacing:0.02em;
  color:var(--bone-faint2);
}

/* ----- doc stage / signature tape element ----- */
.doc-stage{
  position:relative;
  padding-top:26px;
}
.doc-card{
  background:var(--paper-soft);
  color:var(--charcoal);
  border-radius:3px;
  box-shadow:var(--shadow);
  padding:30px 28px 22px;
  position:relative;
  transform:rotate(-0.6deg);
}
.doc-card::before{
  content:"";
  position:absolute;inset:10px;
  border:1px solid var(--paper-line);
  pointer-events:none;
}
.doc-kicker{
  display:flex;
  justify-content:space-between;
  align-items:baseline;
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.06em;
  color:var(--tape-dark);
  text-transform:uppercase;
  padding-bottom:14px;
  border-bottom:1px dashed var(--paper-line);
  margin-bottom:16px;
}
.doc-kicker .live{display:flex;align-items:center;gap:6px;color:#5c6a3a;}
.live-dot{width:6px;height:6px;border-radius:50%;background:#5c8a3a;box-shadow:0 0 0 0 rgba(92,138,58,.6);animation:livepulse 2s infinite;}
@keyframes livepulse{0%{box-shadow:0 0 0 0 rgba(92,138,58,.5);}70%{box-shadow:0 0 0 7px rgba(92,138,58,0);}100%{box-shadow:0 0 0 0 rgba(92,138,58,0);}}

.doc-heading{
  font-family:var(--font-mono);
  font-size:11.5px;
  letter-spacing:0.04em;
  color:var(--charcoal);
  margin-bottom:4px;
}
.doc-body{
  font-family:var(--font-mono);
  font-size:12.5px;
  line-height:1.75;
  color:#3a342c;
}
.doc-body strong{color:var(--charcoal); font-weight:600;}
.doc-foot{
  margin-top:18px;
  padding-top:12px;
  border-top:1px dashed var(--paper-line);
  font-family:var(--font-mono);
  font-size:10.5px;
  color:#7a6f5d;
  letter-spacing:0.02em;
}

/* torn tape across the top of the card */
.tape-row{
  position:absolute;
  top:-14px; left:-14px; right:-14px;
  height:46px;
  display:flex;
  z-index:3;
  pointer-events:none;
}
.tape{
  height:100%;
  background:
    repeating-linear-gradient(128deg, rgba(255,255,255,0.10) 0 3px, transparent 3px 9px),
    linear-gradient(180deg, var(--tape) 0%, var(--tape-dark) 100%);
  box-shadow:0 6px 14px -6px rgba(0,0,0,0.5);
  position:relative;
  overflow:hidden;
  display:flex;
  align-items:center;
}
.tape-left{
  width:52%;
  transform:rotate(-2.2deg);
  clip-path:polygon(0 0,100% 0,90% 22%,100% 42%,86% 58%,100% 78%,92% 100%,0 100%);
}
.tape-right{
  width:52%;
  margin-left:-4%;
  transform:rotate(2.4deg);
  clip-path:polygon(10% 0,100% 0,100% 100%,8% 100%,18% 78%,2% 58%,16% 42%,4% 22%);
}
.tape-text{
  font-family:var(--font-mono);
  font-size:9.5px;
  letter-spacing:0.18em;
  color:rgba(248,240,228,0.55);
  white-space:nowrap;
  padding-left:14px;
  text-transform:uppercase;
}

.seal-stamp{
  position:absolute;
  top:6px; left:50%;
  width:84px;height:84px;
  margin-left:-42px;
  border-radius:50%;
  border:2.5px solid var(--tape-dark);
  display:flex;align-items:center;justify-content:center;
  z-index:4;
  background:rgba(243,236,221,0.0);
  transform:rotate(-9deg) scale(0);
  animation:stampIn .5s cubic-bezier(.2,1.4,.4,1) .55s forwards;
}
.seal-stamp::before{
  content:"";
  position:absolute;inset:7px;
  border:1px dashed var(--tape-dark);
  border-radius:50%;
}
.seal-stamp span{
  font-family:var(--font-mono);
  font-weight:600;
  font-size:11px;
  letter-spacing:0.06em;
  color:var(--tape-dark);
  text-align:center;
  line-height:1.3;
  mix-blend-mode:multiply;
}
@keyframes stampIn{
  0%{transform:rotate(-9deg) scale(1.8); opacity:0;}
  60%{transform:rotate(-9deg) scale(0.92); opacity:1;}
  100%{transform:rotate(-9deg) scale(1); opacity:1;}
}

.pipeline-row{
  margin-top:20px;
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:0;
  font-family:var(--font-mono);
  font-size:11.5px;
}
.pipeline-label{color:var(--bone-faint2); margin-right:10px; letter-spacing:0.05em;}
.chip{
  color:var(--bone-faint);
  padding:5px 10px;
  border:1px solid var(--brass-soft);
  border-radius:30px;
  margin:3px 4px 3px 0;
}
.chip-arrow{color:var(--brass-soft); margin:0 2px;}

/* ============ STATS ============ */
.stats-section{
  border-top:1px solid var(--brass-soft);
  border-bottom:1px solid var(--brass-soft);
  background:var(--ink-panel);
}
.stats-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
}
.stat-cell{
  padding:28px 32px;
  border-right:1px solid var(--brass-soft);
}
.stat-cell:last-child{border-right:none;}
.stat-num{
  font-family:var(--font-mono);
  font-size:28px;
  font-weight:600;
  color:var(--bone);
}
.stat-label{
  margin-top:6px;
  font-size:12.5px;
  color:var(--bone-faint);
  display:flex;
  align-items:baseline;
  gap:6px;
}
.stat-label::before{
  content:"";
  flex:1;
  border-bottom:1px dotted var(--bone-faint2);
  order:2;
  margin-bottom:3px;
  display:none;
}

/* ============ SECTION COMMON ============ */
section{padding:96px 0;}
.section-head{
  max-width:620px;
  margin-bottom:56px;
}
.section-head .eyebrow{color:var(--brass); margin-bottom:14px;}
.section-head h2{
  font-size:clamp(28px,3.2vw,38px);
  color:var(--paper-soft);
  line-height:1.15;
}
.section-head p{
  margin-top:14px;
  color:var(--bone-faint);
  font-size:16px;
  max-width:520px;
}
.light-section{
  background:var(--paper);
  color:var(--charcoal);
}
.light-section .section-head h2{color:var(--charcoal);}
.light-section .section-head p{color:#5b5345;}
.light-section .section-head .eyebrow{color:var(--tape-dark);}

/* ============ PROCESS ============ */
.process-grid{
  position:relative;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:36px;
}
.process-grid::before{
  content:"";
  position:absolute;
  top:27px; left:6%; right:6%;
  height:0;
  border-top:2px dashed var(--brass-soft);
  z-index:0;
}
.process-step{position:relative;}
.stamp-num{
  width:56px;height:56px;
  border-radius:50%;
  background:var(--ink);
  border:2px solid var(--brass);
  color:var(--paper-soft);
  font-family:var(--font-mono);
  font-weight:600;
  font-size:18px;
  display:flex;align-items:center;justify-content:center;
  position:relative;
  z-index:1;
  margin-bottom:22px;
}
.process-step h3{
  font-size:18px;
  color:var(--paper-soft);
  margin-bottom:10px;
  line-height:1.3;
}
.process-step p{
  font-size:14.5px;
  color:var(--bone-faint);
  line-height:1.6;
}
.step-tag{
  display:inline-block;
  margin-top:14px;
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.04em;
  color:var(--brass);
  border-top:1px solid var(--brass-soft);
  padding-top:10px;
}

/* ============ FEATURES / CLAUSES ============ */
.clause-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1px;
  background:var(--paper-line);
  border:1px solid var(--paper-line);
}
.clause{
  background:var(--paper-soft);
  padding:32px 28px;
}
.clause-num{
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--tape-dark);
  letter-spacing:0.08em;
  display:block;
  margin-bottom:14px;
}
.clause h3{
  font-size:18px;
  color:var(--charcoal);
  margin-bottom:10px;
}
.clause p{
  font-size:14.5px;
  color:#5b5345;
  line-height:1.6;
}

/* ============ CASE TYPES ============ */
.case-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:26px;
}
.case-card{
  background:var(--ink-panel);
  border:1px solid var(--brass-soft);
  padding:26px 22px 22px;
  position:relative;
  border-radius:2px;
  transition:transform .2s ease, border-color .2s ease;
}
.case-card:hover{transform:translateY(-4px); border-color:var(--brass);}
.case-card::before{
  content:"";
  position:absolute;
  top:-1px; left:18px;
  width:46px; height:8px;
  background:var(--ink-panel);
  border:1px solid var(--brass-soft);
  border-bottom:none;
  border-radius:3px 3px 0 0;
}
.case-file-no{
  font-family:var(--font-mono);
  font-size:10.5px;
  letter-spacing:0.08em;
  color:var(--bone-faint2);
  display:block;
  margin-bottom:14px;
}
.case-card h3{
  font-size:17px;
  color:var(--bone);
  margin-bottom:6px;
  line-height:1.3;
}
.case-card .case-act{
  font-family:var(--font-display);
  font-style:italic;
  font-size:13.5px;
  color:var(--bone-faint);
}
.case-stamp{
  margin-top:20px;
  display:inline-block;
  font-family:var(--font-mono);
  font-size:10.5px;
  letter-spacing:0.07em;
  text-transform:uppercase;
  border:1.5px solid var(--tape);
  color:var(--tape);
  padding:5px 10px;
  border-radius:2px;
  transform:rotate(-4deg);
}
.case-card:nth-child(2) .case-stamp{transform:rotate(3deg); border-color:#9a7a3c; color:#c9a25a;}
.case-card:nth-child(3) .case-stamp{transform:rotate(-3deg); border-color:var(--brass); color:var(--brass);}
.case-card:nth-child(4) .case-stamp{transform:rotate(5deg);}
.case-card:nth-child(5) .case-stamp{transform:rotate(-5deg);}

/* ============ TESTIMONIAL ============ */
.testimonial-wrap{
  display:grid;
  grid-template-columns:1.3fr 0.9fr;
  gap:56px;
  align-items:center;
}
.quote-mark{
  font-family:var(--font-display);
  font-size:90px;
  color:var(--tape);
  line-height:1;
  margin-bottom:6px;
}
.stars{color:var(--brass); letter-spacing:3px; margin-bottom:18px; font-size:14px;}
blockquote{
  font-family:var(--font-display);
  font-size:24px;
  line-height:1.45;
  color:var(--paper-soft);
  font-weight:400;
  max-width:560px;
}
.cite{
  margin-top:22px;
  display:flex;
  align-items:center;
  gap:12px;
}
.cite-avatar{
  width:42px;height:42px;border-radius:50%;
  background:var(--tape);
  display:flex;align-items:center;justify-content:center;
  font-family:var(--font-mono); font-weight:600; color:var(--paper-soft); font-size:13px;
}
.cite-name{font-size:14.5px; color:var(--bone); font-weight:600;}
.cite-role{font-size:13px; color:var(--bone-faint2);}

.mission-card{
  background:var(--ink-panel);
  border:1px solid var(--brass-soft);
  border-radius:2px;
  padding:36px 30px;
  position:relative;
}
.mission-card::before{
  content:"";
  position:absolute; top:18px; right:18px;
  width:60px;height:60px;
  border:1.5px dashed var(--brass-soft);
  border-radius:50%;
}
.mission-card p.mission-line{
  font-family:var(--font-display);
  font-style:italic;
  font-size:18px;
  line-height:1.5;
  color:var(--paper-soft);
}
.mission-card .mission-sig{
  margin-top:18px;
  font-family:var(--font-mono);
  font-size:11.5px;
  letter-spacing:0.08em;
  color:var(--brass);
  text-transform:uppercase;
}

/* ============ FINAL CTA ============ */
.final-cta{
  background:var(--paper);
  color:var(--charcoal);
  text-align:center;
  padding:110px 0;
  position:relative;
  overflow:hidden;
}
.final-cta::after{
  content:"";
  position:absolute; left:50%; top:0;
  width:1px; height:100%;
  background:repeating-linear-gradient(to bottom, var(--paper-line) 0 6px, transparent 6px 14px);
  opacity:.6;
}
.final-cta h2{
  font-size:clamp(30px,4vw,46px);
  color:var(--charcoal);
  max-width:640px;
  margin:0 auto;
}
.final-cta p{
  margin:18px auto 0;
  color:#5b5345;
  max-width:480px;
  font-size:16px;
}
.final-cta .hero-cta{justify-content:center; margin-top:32px;}

/* ============ FOOTER ============ */
footer{
  background:var(--ink);
  border-top:1px solid var(--brass-soft);
  padding:72px 0 28px;
}
.footer-top{
  display:grid;
  grid-template-columns:1.4fr 0.8fr 0.8fr 0.8fr;
  gap:48px;
}
.footer-brand p{
  margin-top:14px;
  color:var(--bone-faint);
  font-size:14px;
  max-width:300px;
  line-height:1.6;
}
.footer-col h4{
  font-family:var(--font-mono);
  font-size:11.5px;
  letter-spacing:0.1em;
  text-transform:uppercase;
  color:var(--brass);
  margin-bottom:16px;
}
.footer-col ul li{margin-bottom:10px;}
.footer-col ul li a{
  font-size:14px;
  color:var(--bone-faint);
  transition:color .2s ease;
}
.footer-col ul li a:hover{color:var(--bone);}
.footer-bottom{
  margin-top:56px;
  padding-top:24px;
  border-top:1px solid var(--brass-soft);
  display:flex;
  justify-content:space-between;
  align-items:center;
  flex-wrap:wrap;
  gap:16px;
}
.footer-bottom p{
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--bone-faint2);
}
.pill-row{display:flex;gap:10px;flex-wrap:wrap;}
.pill{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.04em;
  border:1px solid var(--brass-soft);
  color:var(--bone-faint);
  padding:5px 12px;
  border-radius:20px;
}

/* ============ SCROLL REVEAL ============ */
.reveal{opacity:0; transform:translateY(14px); transition:opacity .6s ease, transform .6s ease;}
.reveal.in-view{opacity:1; transform:translateY(0);}

@media (prefers-reduced-motion: reduce){
  .reveal{opacity:1; transform:none; transition:none;}
  .seal-stamp{animation:none; transform:rotate(-9deg) scale(1); opacity:1;}
  .live-dot{animation:none;}
  *{scroll-behavior:auto !important;}
}

/* ============ RESPONSIVE ============ */
@media (max-width:1024px){
  .hero-grid{grid-template-columns:1fr; gap:56px;}
  .doc-stage{max-width:520px;}
  .stats-grid{grid-template-columns:repeat(2,1fr);}
  .stat-cell:nth-child(2){border-right:none;}
  .process-grid{grid-template-columns:repeat(2,1fr); row-gap:48px;}
  .process-grid::before{display:none;}
  .clause-grid{grid-template-columns:repeat(2,1fr);}
  .case-grid{grid-template-columns:repeat(2,1fr);}
  .testimonial-wrap{grid-template-columns:1fr; gap:40px;}
  .footer-top{grid-template-columns:1.2fr 1fr 1fr; row-gap:32px;}
}

@media (max-width:760px){
  .wrap{padding:0 20px;}
  .nav-row{padding:14px 20px;}
  .nav-links{
    position:absolute; top:100%; left:0; right:0;
    background:var(--ink-panel);
    flex-direction:column;
    align-items:flex-start;
    padding:18px 20px 22px;
    gap:18px;
    border-bottom:1px solid var(--brass-soft);
    display:none;
  }
  header.site-nav.menu-open .nav-links{display:flex;}
  .nav-actions .nav-signin{display:none;}
  .nav-burger{display:flex;}
  .nav-actions .btn-stamp{padding:10px 16px; font-size:13px;}

  .hero{padding:48px 0 64px;}
  h1.hero-title{font-size:32px;}
  .hero-cta{flex-direction:column; align-items:stretch;}
  .hero-cta .btn{justify-content:center;}

  section{padding:64px 0;}
  .stats-grid{grid-template-columns:repeat(2,1fr);}
  .stat-cell{padding:22px 18px;border-bottom:1px solid var(--brass-soft);}
  .stat-cell:nth-child(odd){border-right:1px solid var(--brass-soft);}

  .process-grid{grid-template-columns:1fr; gap:32px;}
  .clause-grid{grid-template-columns:1fr;}
  .case-grid{grid-template-columns:1fr;}
  .footer-top{grid-template-columns:1fr; row-gap:36px;}
  blockquote{font-size:20px;}
  .final-cta{padding:72px 0;}
}

scriptContent:
// sticky nav shadow on scroll
const nav = document.getElementById('siteNav');
window.addEventListener('scroll', () => {
  nav.classList.toggle('is-scrolled', window.scrollY > 8);
}, { passive: true });

// mobile menu toggle
const burger = document.getElementById('navBurger');
burger.addEventListener('click', () => {
  const open = nav.classList.toggle('menu-open');
  burger.setAttribute('aria-expanded', open ? 'true' : 'false');
});
document.getElementById('navLinks').querySelectorAll('a').forEach(a => {
  a.addEventListener('click', () => {
    nav.classList.remove('menu-open');
    burger.setAttribute('aria-expanded', 'false');
  });
});

// scroll reveal
const reveals = document.querySelectorAll('.reveal');
if ('IntersectionObserver' in window) {
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in-view');
        obs.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  reveals.forEach(el => obs.observe(el));
} else {
  reveals.forEach(el => el.classList.add('in-view'));
}
